import React, { Component } from 'react'
import Container from 'react-bootstrap/Container'
import SearchTable from './SearchTable';
import SearchForm from './SearchForm';

class App extends Component {

  state = {
    commenters: [
              ],
    showSearchTable: false
  }

  /*removeCharacter = index => {
      const { commenters } = this.state

      this.setState({
        formData: commenters.filter((commenters, i) => {
          return i !== index
        }),
      })
  } */

  render() {

    const { commenters } = this.state
    const { showSearchTable } = this.state

      return (
        <Container>
            <h3>Search</h3>
            <SearchForm handleSubmit={this.handleSubmit} />
            <SearchTable commenters={commenters} showSearchTable={showSearchTable} />
        </Container>
      )
  }

  handleSubmit = formData => {

    const requestOptions = {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
    };
    fetch('https://scbm.amfdev.co.uk/api/', requestOptions)
        .then(async response => {
            const data = await response.json();
            console.log(data);
            // check for error response
            if (!response.ok) {
                // get error message from body or default to response status
                const error = (data && data.message) || response.status;
                return Promise.reject(error);
            }

            this.setState({ commenters: data })
            this.setState({ showSearchTable: true })
        })
        .catch(error => {
            //this.setState({ errorMessage: error.toString() });
            console.error('There was an error!', error);
        });


      //this.setState({ commenters: [...this.state.commenters] })
  }

}

export default App
